                                                  \begin{document}$$ \begin{gathered} C_{CI, OM}^{PV} = CRF\left( {20} \right) \cdot P_{PV,r} \cdot N^{PV} \cdot \left( {C_{PV}^{CI} + C_{PV}^{OM} } \right) \hfill \\ C_{CI, OM}^{WT} = CRF\left( {20} \right) \cdot P_{WT,r} \cdot N^{WT} \cdot \left( {C_{WT}^{CI} + C_{WT}^{OM} } \right) \hfill \\ C_{CI, OM,RC}^{BT} = CRF\left( 5 \right) \cdot N^{BT} \cdot (C_{BT}^{CI} + C_{BT}^{OM} + C_{BT}^{OM} \cdot \mathop \sum \limits_{u = 5,10,15} \sigma \left( u \right)) \hfill \\ C_{CI, OM,RC}^{FC} = CRF\left( 5 \right) \cdot P_{\max }^{FC} \cdot N^{FC} \cdot \left( {C_{FC}^{CI} + C_{FC}^{OM} + C_{FC}^{OM} .\mathop \sum \limits_{u = 5,10,15} \sigma \left( u \right)} \right) \hfill \\ C_{CI, OM,RC}^{EL} = CRF\left( {10} \right) \cdot P_{\max }^{EL} \cdot N^{EL} \cdot \left( {C_{EL}^{CI} + C_{EL}^{OM} + C_{EL}^{OM} \cdot \sigma \left( {10} \right)} \right) \hfill \\ C_{CI, OM}^{HT} = CRF\left( {10} \right) \cdot m_{r}^{HT} \cdot N^{HT} \cdot \left( {C_{HT}^{CI} + C_{HT}^{OM} } \right) \hfill \\ \end{gathered} $$\end{document}

